const orders = $input.all().map(i => i.json);

// Group customers by first purchase month (cohort)
const customerCohort = {};
const customerActivity = {};

orders.forEach(o => {
  const email = o['Customer Email'];
  const date = new Date(o['Order Date']);
  const monthKey = `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`;
  const value = parseFloat(o['Order Value']||0);

  if (!customerActivity[email]) customerActivity[email] = [];
  customerActivity[email].push({ month: monthKey, value });
});

// Find first purchase month per customer
Object.entries(customerActivity).forEach(([email, activity]) => {
  const sorted = activity.sort((a,b) => a.month.localeCompare(b.month));
  const cohort = sorted[0].month;
  if (!customerCohort[cohort]) customerCohort[cohort] = { cohort_month: cohort, customers: [], size: 0 };
  customerCohort[cohort].customers.push({ email, activity: sorted });
  customerCohort[cohort].size++;
});

// Calculate retention by cohort
const cohorts = Object.values(customerCohort).sort((a,b) => a.cohort_month.localeCompare(b.cohort_month)).slice(-6);

const cohortData = cohorts.map(c => {
  const retentionByPeriod = {};
  c.customers.forEach(cust => {
    cust.activity.forEach(act => {
      const periodIndex = act.month.localeCompare(c.cohort_month) === 0 ? 0 :
        (new Date(act.month).getFullYear() * 12 + new Date(act.month).getMonth()) -
        (new Date(c.cohort_month).getFullYear() * 12 + new Date(c.cohort_month).getMonth());
      if (!retentionByPeriod[periodIndex]) retentionByPeriod[periodIndex] = new Set();
      retentionByPeriod[periodIndex].add(cust.email);
    });
  });

  const retention = {};
  Object.entries(retentionByPeriod).forEach(([period, customers]) => {
    retention[`period_${period}`] = { count: customers.size, rate: ((customers.size/c.size)*100).toFixed(1) };
  });

  return { cohort_month: c.cohort_month, cohort_size: c.size, retention };
});

return [{ json: { cohorts: cohortData, total_cohorts: cohortData.length } }];

const raw = $input.item.json.text.replace(/```json|```/g,'').trim();
const analysis = JSON.parse(raw);
return [{ json: { ...analysis, cohort_data: $('Build Cohort Table').item.json } }];

